/* Design: choose an edge skew to a given line; any correct choice scores. Options are in a fixed order; several are correct, so the teacher's answer is the first correct one. Each wrong option has its own feedback (parallel or meets). Source: original. */
ix: 1+rand(10); TT: tlist[ix];
g: TT[1]; skE: TT[2]; skD: TT[3]; REL: TT[4];
andlist(L) := if length(L) = 1 then L[1] else sconcat(simplode(rest(L,-1), ", "), " and ", last(L));
oE: delete(g, ["AB","AC","AD","BC","BE","CF","DE","DF","EF"]);
oD: delete(g, ["AE","BD","AF","CD","BF","CE"]);
cE: sublist(oE, lambda([e], member(e, skE))); cD: sublist(oD, lambda([e], member(e, skD)));
opt1: makelist([e, is(e = cE[1]), e], e, oE); opt2: makelist([e, is(e = cD[1]), e], e, oD);
ta1: cE[1]; ta2: cD[1]; tb1: cE[2]; tb2: cD[2];
pE: sublist(oE, lambda([e], is(first(sublist(REL, lambda([r], is(r[1] = e))))[2] = "par")));
iE: sublist(oE, lambda([e], is(first(sublist(REL, lambda([r], is(r[1] = e))))[2] = "int")));
iD: sublist(oD, lambda([e], is(first(sublist(REL, lambda([r], is(r[1] = e))))[2] = "int")));
w1: if pE = [] then iE[1] else pE[1]; w2: iE[1]; wd: iD[1]; wd2: last(iD);
sE: andlist(skE); sD: andlist(skD);

feedbackvariables.text:
in1: member(ans1, skE); in2: member(ans2, skD);
rv1: sublist(REL, lambda([r], is(r[1] = ans1))); rv2: sublist(REL, lambda([r], is(r[1] = ans2)));
fb1: if rv1 = [] then "" else rv1[1][3]; fb2: if rv2 = [] then "" else rv2[1][3];

in1: member(ans1, skE); in2: member(ans2, skD);
rv1: sublist(REL, lambda([r], is(r[1] = ans1))); rv2: sublist(REL, lambda([r], is(r[1] = ans2)));
fb1: if rv1 = [] then "" else rv1[1][3]; fb2: if rv2 = [] then "" else rv2[1][3];
